Lemma astack_ok_of_astk M M1 sp scr fr scr' :
  astk ar M sp scr -> mem_grows M M1 -> 0 <= fr -> 0 <= scr' -> fr + scr' <= scr -> (sp - fr) mod 16 = 0 ->
