(* [comment removed for export] *)
Lemma ek_mem LB FF sp scr sp' scr' (D : Z -> Prop) W M M' :
  (forall a, 0 <= a < 2 ^ 64 -> aclient L ar LB FF sp' scr' a -> ~ D a -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
