Record gctx : Prop := GCTX {
  g_k : In k [0; 1; 2; 3; 4; 5];
  g_SPT : 140735340871680 <= ar_sptop ar <= 2 ^ 47;
  g_SLO : ahl_ceil ar + 4096 + SCR <= sp;
